-- PT105-S4-Q9. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT105-S4-Q9$batch11$ AND q.stimulus=$batch11$To allay public concern about chemicals that are leaking into a river from a chemical company's long established dump, a company representative said, "Federal law requires that every new chemical be tested for safety before it is put onto the market. This is analogous to the federal law mandating testing of every pharmaceutical substance for safety."$batch11$ AND q.prompt=$batch11$Which one of the following, if true, most seriously weakens the representative's implied argument that the public need not be concerned about the leak?$batch11$ AND q.correct_choice=$batch11$C$batch11$) THEN RAISE EXCEPTION 'Question changed: PT105-S4-Q9'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT105-S4-Q9$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT105-S4-Q9'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT105-S4-Q9$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Conclusion$batch11$, $batch11$The representative implies that the public need not be concerned about the chemicals leaking from the dump.$batch11$), (1, $batch11$Evidence$batch11$, $batch11$Federal law requires every new chemical to be tested for safety before it goes to market, just as pharmaceuticals are tested.$batch11$), (2, $batch11$Evaluate$batch11$, $batch11$The law covers new chemicals. The dump is long established, so its chemicals may be older than the law. If dangerous chemicals were in use before testing began, the law does nothing to show the leak is safe.$batch11$), (3, $batch11$Goal$batch11$, $batch11$Show the leaking chemicals may never have been tested.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT105-S4-Q9$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$A drawback of drug testing doesn't touch the safety of the leaking chemicals.$batch11$), ($batch11$B$batch11$, $batch11$When the leak became noticeable doesn't say whether the chemicals are safe.$batch11$), ($batch11$C$batch11$, $batch11$The testing law is recent, and thousands of chemicals, many dangerous, were already in use. The dump's old chemicals likely escaped testing.$batch11$), ($batch11$D$batch11$, $batch11$Dilution makes the leak less worrying, if anything.$batch11$), ($batch11$E$batch11$, $batch11$Silt making the river murky has nothing to do with chemical safety.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT105-S4-Q9$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
